  it: {
    intro: { label: "Progettazione 3D fotovoltaica", heading: "Configuri insieme tetto, pannelli e modello energetico domestico.", body: "Il configuratore fotovoltaico 360Configurator collega geometria del tetto, disposizione dei pannelli, contesto geografico, posizione del sole, consumi domestici e accumulo a batteria in un unico modello interattivo. Mostra non solo come un impianto fotovoltaico si colloca sul tetto, ma anche come la taglia del sistema e le ipotesi di consumo incidono sul bilancio energetico.", launch: "Apri il configuratore fotovoltaico 3D", learn: "Scopra come funziona" },
    workflow: { label: "Come funziona", heading: "Da posizione e tetto a uno scenario energetico giornaliero in cinque passaggi.", intro: "Il flusso fotovoltaico unisce la disposizione spaziale alle ipotesi energetiche, così l’impianto può essere valutato sia come prodotto installato sul tetto sia come sistema energetico.", steps: [
      { title: "Imposti posizione e orientamento", body: "Usi la posizione del progetto e l’orientamento della falda come contesto per la posizione del sole e le ipotesi di produzione." },
      { title: "Configuri il tetto", body: "Scelga la tipologia di copertura supportata e ne regoli dimensioni e pendenza, così le superfici fotovoltaiche disponibili corrispondono all’edificio." },
      { title: "Disponga i pannelli", body: "Scelga il numero di moduli e la falda; il configuratore dispone moduli di taglia residenziale sulla superficie utile del tetto." },
      { title: "Modelli consumi e accumulo", body: "Selezioni un profilo di consumo domestico e attivi o dimensioni una batteria LiFePO₄ per confrontare come viene usata la produzione solare durante la giornata." },
      { title: "Verifichi il risultato energetico", body: "Consulti kWp installati, produzione, fabbisogno domestico, autosufficienza, prelievo e immissione in rete e il profilo giornaliero di produzione e consumi." },
    ] },
    decisions: { label: "Cosa può configurare", heading: "Colleghi la disposizione fisica dei pannelli alle scelte energetiche.", intro: "Una configurazione fotovoltaica utile richiede più del numero di pannelli. Disposizione sul tetto, orientamento, orari di consumo e accumulo influenzano tutti il risultato.", groups: [
      { title: "Posizione e sole", body: "Definisca il contesto ambientale del sistema attuale.", items: ["Indirizzo / coordinate del progetto", "Orientamento della falda", "Ora e data", "Posizione stagionale del sole", "Dati calibrati PVGIS / del sito esatto, ove disponibili"] },
      { title: "Tetto e disposizione pannelli", body: "Costruisca la superficie fisica su cui l’impianto deve trovare posto.", items: ["Tetto a due falde", "Tetto a padiglione", "Tetto a una falda", "Dimensioni e pendenza del tetto", "Posa dei moduli a grandezza reale"] },
      { title: "Consumi e accumulo", body: "Verifichi come le abitudini domestiche cambiano il valore dello stesso impianto.", items: ["Profili di consumo residenziale", "Consumo annuo", "Batteria LiFePO₄", "Dimensionamento automatico o manuale della batteria"] },
      { title: "Vista energetica e commerciale", body: "Esamini il sistema risultante come scenario energetico giornaliero.", items: ["kWp installati", "Produzione fotovoltaica", "Autosufficienza", "Prelievo e immissione in rete", "Stima del sistema"] },
    ] },
    outcomes: { label: "Perché configurare in 3D", heading: "Una proposta fotovoltaica che unisce tetto e comportamento energetico.", body: "Disposizione dei pannelli e prestazioni energetiche vengono spesso trattate in strumenti separati. Unirle rende più facile spiegare perché un sistema ha una certa taglia, dove si collocano i moduli e come le ipotesi di consumo o di accumulo cambiano il risultato.", items: [
      { title: "Per il proprietario", body: "Veda dove si trovano i pannelli sul tetto e confronti produzione, consumi e accumulo in un’unica vista comprensibile." },
      { title: "Per i team commerciali", body: "Mantenga sincronizzati geometria del tetto, numero di pannelli, potenza installata e scenario energetico nella stessa trattativa." },
      { title: "Per la progettazione tecnica", body: "Usi contesto del sito, disposizione sul tetto e dati PVGIS, ove disponibili, come base più solida per una progettazione di dettaglio." },
    ] },
    faq: { label: "FAQ configuratore fotovoltaico", heading: "Domande frequenti sul configuratore fotovoltaico 3D.", items: [
      { question: "Quali tipologie di tetto posso usare per l’impianto?", answer: "Il configuratore attuale supporta tetti residenziali a due falde, a padiglione e a una falda." },
      { question: "Posso modificare dimensioni e pendenza del tetto?", answer: "Sì. Lunghezza, profondità e pendenza sono configurabili e le superfici disponibili per i pannelli si ricostruiscono con il tetto." },
      { question: "Il configuratore usa la posizione del progetto?", answer: "Sì. La posizione fa da contesto per la posizione del sole e le ipotesi di produzione del sito; il progetto supporta anche i dati PVGIS tramite il flusso proxy configurato." },
      { question: "I pannelli sono posizionati a grandezza reale?", answer: "Sì. L’anteprima attuale usa dimensioni di moduli residenziali e lega la potenza installata ai moduli che trovano posto sulla falda scelta." },
      { question: "Posso modellare i consumi domestici?", answer: "Sì. Il configuratore include diversi profili di consumo diurno e un campo per il consumo annuo nel modello energetico." },
      { question: "Posso aggiungere un accumulo a batteria?", answer: "Sì. L’accumulo LiFePO₄ può essere attivato, dimensionato automaticamente o regolato manualmente con i comandi disponibili." },
      { question: "Quali risultati energetici vengono mostrati?", answer: "L’analisi attuale comprende produzione fotovoltaica, fabbisogno domestico, autosufficienza, prelievo e immissione in rete, accumulo e potenza installata." },
    ] },
    finalCta: { eyebrow: "Provi il prodotto reale", heading: "Crei uno scenario fotovoltaico sul tetto nel browser.", body: "Apra il configuratore fotovoltaico per provare geometria del tetto, disposizione dei moduli, posizione del sole, consumi domestici e accumulo, oppure ci contatti per un configuratore del suo prodotto energetico.", launch: "Avvia il configuratore fotovoltaico", contact: "Parliamo di un progetto di configuratore" },
  },
